/**
 * Antigravity's identity on the key faces: a teal accent (apart from Claude
 * orange, Kimi blue, Gemini violet and the session status colours) and a
 * generic mark, an arch with a dot floating under it, drawn with canvas
 * primitives in the accent colour; not Google's logo, no logo file. Owned
 * by the architect: implementers do not edit this file.
 */
import type { Brand, KeyMark } from '../types';

const ACCENT = '#2ec4a6';
const DOT = '#fafaf9';

const antigravityMark: KeyMark = {
  draw(ctx, x, y, size) {
    const s = size;
    const at = (fx: number, fy: number): [number, number] => [
      x + fx * s,
      y + fy * s,
    ];
    // the arch: legs flaring out at the bottom, a round top
    ctx.strokeStyle = ACCENT;
    ctx.lineWidth = 0.17 * s;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.moveTo(...at(0.11, 0.87));
    ctx.bezierCurveTo(...at(0.3, 0.76), ...at(0.3, 0.12), ...at(0.5, 0.12));
    ctx.bezierCurveTo(...at(0.7, 0.12), ...at(0.7, 0.76), ...at(0.89, 0.87));
    ctx.stroke();
    // the dot floating under the arch
    ctx.fillStyle = DOT;
    ctx.beginPath();
    ctx.arc(...at(0.5, 0.67), 0.095 * s, 0, Math.PI * 2);
    ctx.fill();
  },
};

export const ANTIGRAVITY_BRAND: Brand = {
  name: 'Antigravity',
  productName: 'Antigravity',
  accent: ACCENT,
  mark: antigravityMark,
};
